insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_94_v1'
from (values
('127.747.d.1.A',3,'A student studies how county jails, state prisons and federal penitentiaries each developed over time. This is examining:','["the history of corrections at several levels", "only weather history", "only cooking history", "only sports history"]'::jsonb,0,'Corrections history spans municipal to federal levels.','original'),
('127.747.d.1.A',4,'Which statement fits the history of corrections in the United States?','["Corrections never changed", "Facilities and reform ideas changed as laws and public views changed", "Only one prison has ever existed", "Prisons began in space"]'::jsonb,1,'The system evolved over time.','original'),
('127.747.d.1.B',3,'A new jailer reads the employee handbook to learn the code of conduct and what happens after a violation. This is studying:','["recipes", "bus routes", "rules of conduct and disciplinary guidelines", "sports scores"]'::jsonb,2,'Employees must know conduct rules.','original'),
('127.747.d.1.B',4,'Why must correctional employees follow written conduct rules?','["They are optional", "They are decorations", "They apply only to inmates", "They keep staff accountable and the facility safe and lawful"]'::jsonb,3,'Rules protect staff, inmates and the public.','original'),
('127.747.d.1.C',3,'A student considers whether she can handle shift work, close contact with inmates and strict rules before choosing a corrections career. This is:','["analyzing personal responsibilities and preferences against job requirements", "choosing at random", "ignoring the job", "avoiding all careers"]'::jsonb,0,'Self-assessment matches people to careers.','original'),
('127.747.d.1.C',4,'Which question best helps a person decide if corrections fits them?','["Do the guards like pizza?", "Am I comfortable with structure, shift work and enforcing rules?", "What color is the building?", "Is the parking lot big?"]'::jsonb,1,'Fit depends on job demands.','original'),
('127.747.d.1.D',3,'A graduate looks at county, state and federal job boards and calls a sheriff''s office about openings. This is:','["ignoring openings", "quitting school", "searching effectively for employment in corrections", "avoiding work"]'::jsonb,2,'Job search uses multiple sources.','original'),
('127.747.d.1.D',4,'Which source is most useful for finding open correctional officer positions in a county?','["A TV ad for snacks", "A rumor", "A random social post", "The county''s official employment page"]'::jsonb,3,'Official pages list real openings.','original'),
('127.747.d.2.A',3,'An employer lists clear speaking, punctuality and honesty as top expectations for jailers. These are:','["employer expectations in corrections", "vacation plans", "school lunches", "student privileges"]'::jsonb,0,'Employers expect these traits.','original'),
('127.747.d.2.A',4,'Arriving on time, following orders and communicating clearly all show that an employee meets:','["only student goals", "employer expectations", "only personal goals", "no expectations"]'::jsonb,1,'They are common workplace expectations.','original'),
('127.747.d.2.B',3,'A state prison requires its officers to meet standards for training, fitness and ethics. These are:','["gym rules for visitors", "menu choices", "professional standards in correctional work", "school dress codes"]'::jsonb,2,'Standards set the level of professional work.','original'),
('127.747.d.2.B',4,'Professional standards in corrections help ensure that officers:','["choose rules at will", "avoid all training", "ignore laws", "perform duties competently and ethically"]'::jsonb,3,'Standards maintain quality.','original'),
('127.747.d.2.C',3,'A correctional officer refuses a bribe from an inmate''s family to smuggle in a phone. This protects:','["the ethical responsibility to safeguard people and the facility", "only the officer''s pay", "nothing", "only the family"]'::jsonb,0,'Contraband puts everyone at risk.','original'),
('127.747.d.2.C',4,'An officer''s ethical duty to protect inmates'' safety includes:','["joining in", "preventing harm and reporting abuse", "hiding reports", "ignoring abuse"]'::jsonb,1,'Officers must protect those in custody.','original'),
('127.747.d.3.A',3,'A trainee learns what ''classification'', ''contraband'' and ''segregation'' mean in jail work. This is defining:','["music terms", "cooking terms", "technical concepts and vocabulary of corrections", "sports terms"]'::jsonb,2,'Vocabulary supports clear communication.','original'),
('127.747.d.3.A',4,'Which term describes illegal or prohibited items in a secure facility?','["receipt", "curriculum", "ballot", "contraband"]'::jsonb,3,'Contraband is banned material.','original'),
('127.747.d.3.B',3,'During a staff meeting about a lockdown drill, a trainee nods, takes notes and adds a suggestion when asked. This shows:','["active listening and contributing to group discussion", "interrupting", "sleeping", "ignoring the group"]'::jsonb,0,'Participation includes listening and contributing.','original'),
('127.747.d.3.B',4,'Which behavior best shows active listening in a shift briefing?','["Leaving early", "Taking notes and asking relevant questions", "Talking over others", "Looking at a phone"]'::jsonb,1,'Active listeners engage.','original'),
('127.747.d.4.A',3,'A supervisor gives instructions over the radio and the officer repeats them back to confirm. This is applying:','["ignoring orders", "guessing", "listening skills to obtain and clarify information", "interrupting"]'::jsonb,2,'Repeating back confirms understanding.','original'),
('127.747.d.4.A',4,'An officer is unsure what a supervisor meant by ''secure the block.'' The best action is to:','["leave the post", "do nothing", "guess", "ask a clarifying question"]'::jsonb,3,'Clarify to avoid mistakes.','original'),
('127.747.d.4.B',3,'A veteran officer explains to a rookie what ''count'', ''sally port'' and ''tier'' mean. This is:','["explaining technical vocabulary in plain terms", "hiding information", "avoiding communication", "using slang only"]'::jsonb,0,'Clear explanation helps new staff.','original'),
('127.747.d.4.B',4,'When explaining a facility term to a new volunteer, the best approach is to:','["use more jargon", "use simple words and examples", "say nothing", "walk away"]'::jsonb,1,'Plain language aids understanding.','original'),
('127.747.d.5.A',3,'A jailer finds an inmate unresponsive and begins CPR while calling for help and an AED. This is applying:','["only paperwork", "ignoring the emergency", "first aid, CPR and AED procedures", "avoiding the incident"]'::jsonb,2,'Emergency care saves lives.','original'),
('127.747.d.5.A',4,'What should an officer do first when finding an unresponsive person?','["Move the person at once", "Wait quietly", "Leave", "Check the scene for safety and call for help"]'::jsonb,3,'Safety and help come first.','original'),
('127.747.d.5.B',3,'An officer wears gloves before touching an inmate''s bleeding cut. This follows:','["standard precautions for infection control", "an outdated rule", "spreading germs", "ignoring safety"]'::jsonb,0,'Gloves block exposure to blood.','original'),
('127.747.d.5.B',4,'Standard precautions treat all blood and body fluids as:','["food", "potentially infectious", "always safe", "valueless"]'::jsonb,1,'Everyone follows the same protection.','original'),
('127.747.d.5.C',3,'A kitchen worker in a jail must follow Safety Data Sheet instructions for a cleaning chemical. This is:','["skipping gloves", "mixing chemicals", "using special requirements for hazardous materials to stay safe", "ignoring labels"]'::jsonb,2,'SDS guide safe handling.','original'),
('127.747.d.5.C',4,'Which practice is correct when handling a hazardous cleaning product at a facility?','["Skip gloves", "Store it unlabeled", "Mix it with other cleaners", "Read the label and wear the recommended protective gear"]'::jsonb,3,'Follow safety directions.','original'),
('127.747.d.6.A',3,'An officer needs lawful grounds before taking a person into custody. This shows applying:','["constitutional laws, including laws of arrest", "random rules", "guesswork", "personal opinion"]'::jsonb,0,'Arrests must meet legal rules.','original'),
('127.747.d.6.A',4,'Why must corrections staff know constitutional law?','["It has no use", "Their actions must respect inmates'' and citizens'' legal rights", "It makes shifts shorter", "It is only for judges"]'::jsonb,1,'Rights limit what officers may do.','original'),
('127.747.d.6.B',3,'A court ruling changes how facilities must provide medical care to inmates. This is an example of:','["no connection", "a weather effect", "the impact of the U.S. legal system on corrections", "a cooking rule"]'::jsonb,2,'Courts shape correctional practice.','original'),
('127.747.d.6.B',4,'Court decisions can influence corrections by:','["ending all prisons", "deleting policies", "removing all rules", "setting standards for conditions and treatment"]'::jsonb,3,'Rulings set legal requirements.','original'),
('127.747.d.6.C',3,'A person sues a neighbor over a fence, while another is charged by the state for burglary. These examples show the difference between:','["the civil and criminal justice systems", "two sports leagues", "two weather systems", "two school districts"]'::jsonb,0,'Civil is private disputes; criminal is offenses against the state.','original'),
('127.747.d.6.C',4,'A key difference between civil and criminal cases is that criminal cases:','["never use evidence", "are brought by the government and can result in jail or prison", "never reach court", "are always private"]'::jsonb,1,'The state prosecutes crimes.','original'),
('127.747.d.6.D',3,'An officer calmly separates two arguing inmates and speaks quietly to lower tension. This is using:','["ignoring the problem", "escalation", "techniques to manage a crisis and protect rights", "shouting"]'::jsonb,2,'De-escalation protects everyone.','original'),
('127.747.d.6.D',4,'Which action is an appropriate first step in managing an inmate crisis?','["Walk away", "Use force immediately", "Argue loudly", "Stay calm, assess the situation and use verbal de-escalation"]'::jsonb,3,'Calm assessment comes first.','original'),
('127.747.d.6.E',3,'An officer must follow state law and procedure when conducting a search after an arrest. This shows:','["executing arrest, search and seizure protocols lawfully", "skipping steps", "ignoring statutes", "searching at random"]'::jsonb,0,'Legal procedure protects evidence and rights.','original'),
('127.747.d.6.E',4,'Evidence obtained from an unlawful search may be:','["automatically sealed", "excluded from court", "always accepted", "worth extra points"]'::jsonb,1,'The exclusionary rule applies.','original'),
('127.747.d.6.F',3,'Before questioning a suspect in custody, an officer reads the Miranda warning. This reflects the:','["right to free food", "right to vote", "Fifth Amendment protection against self-incrimination", "right to travel"]'::jsonb,2,'Miranda rights stem from the Fifth Amendment.','original'),
('127.747.d.6.F',4,'The Fifth Amendment gives a person in custody the right to:','["skip the trial", "avoid all questions forever", "choose the judge", "remain silent and not incriminate themselves"]'::jsonb,3,'Silence is protected.','original'),
('127.747.d.6.G',3,'A defendant is tried by a jury of citizens and has a fair hearing under the law. This reflects:','["trial, jury and due process rights", "no process", "lost rights", "no rights"]'::jsonb,0,'These are core legal rights.','original'),
('127.747.d.6.G',4,'Due process means that the government must:','["skip hearings", "follow fair procedures before taking life, liberty or property", "ignore laws", "act however it wants"]'::jsonb,1,'Fair procedure is required.','original'),
('127.747.d.6.H',3,'Citizens and non-citizens alike must be treated lawfully when detained, but in some cases federal law governs how non-citizens are held. This asks when:','["only adults pay fines", "only tourists can be", "citizens and non-citizens may be lawfully detained", "no one can be detained"]'::jsonb,2,'Detention rules are set by law.','original'),
('127.747.d.6.H',4,'Which principle applies to anyone held in custody in the United States?','["Only citizens have protection", "They may be held forever without review", "No rules apply", "They must be held lawfully and treated according to the law"]'::jsonb,3,'Legal protections apply broadly.','original'),
('127.747.d.7.A',3,'An inmate shows signs of a serious mental disorder and an officer follows facility procedures to request mental health staff. This is:','["applying appropriate procedures for individuals with mental disorders", "ignoring the inmate", "laughing", "punishing symptoms"]'::jsonb,0,'Mental health needs special handling.','original'),
('127.747.d.7.A',4,'When an inmate appears disoriented and talks to unseen people, officers should:','["ignore it", "notify supervisors and mental health staff", "use force at once", "make fun"]'::jsonb,1,'Refer to qualified staff.','original'),
('127.747.d.7.B',3,'An officer arranges for an inmate who uses a wheelchair to reach the dining hall safely. This is:','["blocking entry", "ignoring needs", "executing protocols to assist people with disabilities", "denying access"]'::jsonb,2,'Accessibility is required.','original'),
('127.747.d.7.B',4,'Which action best assists an inmate who is hard of hearing during a briefing?','["Shout from behind", "Ignore the need", "Use only jargon", "Face the person, speak clearly and provide written instructions"]'::jsonb,3,'Provide an effective accommodation.','original'),
('127.747.d.7.C',3,'The Americans with Disabilities Act requires jails to provide equal access to programs. This is its impact on:','["inmates and correctional facilities", "only schools", "only stadiums", "only airports"]'::jsonb,0,'ADA applies to correctional programs.','original'),
('127.747.d.7.C',4,'The ADA prohibits correctional facilities from:','["housing inmates", "discriminating against people with disabilities in programs and services", "giving meals", "using locks"]'::jsonb,1,'Discrimination is illegal.','original'),
('127.747.d.8.A',3,'A counselor explains that conflicts often start when basic needs like respect or safety are threatened. This is examining:','["unrelated hobbies", "ignoring people", "the origins of conflict and the needs behind behavior", "sports rules"]'::jsonb,2,'Needs drive behavior.','original'),
('127.747.d.8.A',4,'Which need most often triggers conflict in a crowded dayroom?','["weather reports", "video games", "pizza topping choice", "a need for respect or personal space"]'::jsonb,3,'Needs for respect and space trigger tension.','original'),
('127.747.d.8.B',3,'One officer answers an insult with a threat and the argument gets louder. Another answers calmly and it fades. This is analyzing:','["different responses to conflict and their results", "only weather", "random luck", "no responses"]'::jsonb,0,'Responses shape outcomes.','original'),
('127.747.d.8.B',4,'Which response to conflict is most likely to lower tension?','["Ignoring safety", "Listening and responding calmly", "Escalating insults", "Threatening"]'::jsonb,1,'Calm responses calm others.','original'),
('127.747.d.8.C',3,'Two staff members each state their concerns, separate the problem from the person and agree on a solution. This is:','["blaming", "winning at all costs", "principle-centered conflict resolution", "avoiding conflict"]'::jsonb,2,'Focus on interests and solutions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_94_v1'
from (values
('127.747.d.8.C',4,'A key step in principle-centered conflict resolution is to:','["assign blame first", "ignore the other side", "win by force", "focus on interests and shared goals"]'::jsonb,3,'Solutions come from interests.','original'),
('127.747.d.8.D',3,'An officer notices an inmate''s clenched fists, raised voice and fast pacing and decides the person is angry. This is:','["interpreting visual and vocal cues", "only paperwork", "random guessing", "ignoring signs"]'::jsonb,0,'Body language and tone carry meaning.','original'),
('127.747.d.8.D',4,'Rapid pacing, loud speech and tense posture most likely indicate:','["hunger only", "agitation or anger", "calm", "sleepiness"]'::jsonb,1,'These cues show agitation.','original'),
('127.747.d.9.A',3,'A new officer reviews what to do at the control room, the main gate and a housing unit. This is:','["avoiding duty", "learning to cook", "reviewing security post procedures", "playing games"]'::jsonb,2,'Each post has written procedures.','original'),
('127.747.d.9.A',4,'Why do security posts have written procedures?','["To fill space", "To confuse staff", "They don''t matter", "So every officer performs duties the same safe way"]'::jsonb,3,'Procedures keep operations consistent.','original'),
('127.747.d.9.B',3,'Fences, cameras and a patrol road around a prison make up its:','["perimeter security system", "parking lot", "school grounds", "visitor center"]'::jsonb,0,'Perimeters prevent escape and intrusion.','original'),
('127.747.d.9.B',4,'A perimeter security system is important because it helps:','["bring in contraband", "prevent escapes and keep unauthorized people out", "reduce staffing", "hide visitors"]'::jsonb,1,'It controls entry and exit.','original'),
('127.747.d.9.C',3,'An officer chooses to use only the minimum force needed to stop a physical threat. This is:','["excessive force", "random action", "appraising the situation and selecting appropriate force", "ignoring danger"]'::jsonb,2,'Force must be proportional.','original'),
('127.747.d.9.C',4,'The principle that force must match the level of threat is called:','["no force ever", "unlimited force", "force by rank", "the use of reasonable and proportional force"]'::jsonb,3,'Force should be necessary and reasonable.','original'),
('127.747.d.9.D',3,'A facility drills evacuation, lockdown and staff roles before an emergency occurs. This is:','["pre-event planning to respond to crises", "ignoring risk", "random action", "post-event cleanup"]'::jsonb,0,'Planning ahead improves response.','original'),
('127.747.d.9.D',4,'Pre-event planning for a crisis includes:','["waiting until it happens", "assigning roles, practicing drills and stocking supplies", "avoiding drills", "hiding plans"]'::jsonb,1,'Preparation improves response.','original'),
('127.747.d.9.E',3,'During a disturbance, an officer follows crisis protocols to protect staff and inmates and respect their rights. This is:','["leaving", "using unlimited force", "performing crisis management to protect individual and societal rights", "ignoring the event"]'::jsonb,2,'Crisis management balances safety and rights.','original'),
('127.747.d.9.E',4,'Effective crisis management in a facility aims to:','["hide the event", "increase conflict", "punish everyone", "restore order while protecting safety and rights"]'::jsonb,3,'The goal is safe resolution.','original'),
('127.747.d.10.A',3,'An officer follows written rules for supervising inmates and handing out discipline fairly. This shows knowledge of:','["policies and procedures for supervision and discipline", "random choices", "personal opinion", "no rules"]'::jsonb,0,'Consistent procedures keep order.','original'),
('127.747.d.10.A',4,'Why must inmate discipline follow written policy?','["It speeds paperwork", "It ensures fairness and legal compliance", "It looks nice", "It saves ink"]'::jsonb,1,'Policy prevents abuse.','original'),
('127.747.d.10.B',3,'An officer uses an approved technique to place restraints on a resisting person while avoiding injury. This is:','["guesswork", "unlawful force", "protocol designed to restrain individuals without harm", "ignoring training"]'::jsonb,2,'Approved methods limit injury.','original'),
('127.747.d.10.B',4,'Proper restraint protocol aims to:','["cause pain", "skip documentation", "delay response", "control a person safely with minimal risk of injury"]'::jsonb,3,'Safety for all is the aim.','original'),
('127.747.d.10.C',3,'A facility plans how staff will respond to fires, storms and hostage situations. This is developing:','["emergency plans and procedures for correctional facilities", "recipes", "class schedules", "sports lineups"]'::jsonb,0,'Plans cover many emergencies.','original'),
('127.747.d.10.C',4,'A facility emergency plan should be:','["never practiced", "written, practiced and updated regularly", "secret from staff", "rarely read"]'::jsonb,1,'Plans are only useful if known and current.','original'),
('127.747.d.10.D',3,'Kitchen staff in a jail must follow safe food-handling rules to prevent illness. This describes:','["no rules", "only weather", "the process and critical elements of food services", "only sports"]'::jsonb,2,'Food service needs safety and controls.','original'),
('127.747.d.10.D',4,'A critical element of food services in a facility is:','["serving unlabeled food", "random cooking", "ignoring allergies", "safe preparation and controlled distribution"]'::jsonb,3,'Safety and control matter.','original'),
('127.747.d.10.E',3,'A new inmate arrives, is searched, photographed, classified and given an orientation. This is the:','["steps for processing inmates", "court trial", "parole process", "release process"]'::jsonb,0,'Intake includes reception, orientation and classification.','original'),
('127.747.d.10.E',4,'Classification of a new inmate determines:','["only cell color", "housing, security level and program needs", "only uniform color", "visiting hours only"]'::jsonb,1,'Classification guides placement.','original'),
('127.747.d.10.F',3,'A student role-plays a parole board interviewer asking an inmate about plans after release. This is:','["an arrest", "a trial", "conducting a simulated parole interview", "a sentencing hearing"]'::jsonb,2,'Parole interviews assess readiness for release.','original'),
('127.747.d.10.F',4,'During a parole interview, an inmate''s plan should show:','["only complaints", "only excuses", "no plans", "housing, work and support after release"]'::jsonb,3,'Boards want a realistic plan.','original'),
('127.747.d.10.G',3,'A program that provides job training and counseling to people leaving prison is a:','["prisoner re-entry program", "recipe class", "sports camp", "school fair"]'::jsonb,0,'Re-entry programs help people return to society.','original'),
('127.747.d.10.G',4,'Re-entry programs aim to reduce:','["employment", "the chance that people reoffend", "education", "housing"]'::jsonb,1,'They support successful return.','original'),
('127.747.d.10.H',3,'A facility holds an open house and tells residents how it keeps the neighborhood safe. This shows the importance of:','["secrecy", "conflict", "public relations with communities and citizens", "isolation"]'::jsonb,2,'Good relations build trust.','original'),
('127.747.d.10.H',4,'Public relations matters to a correctional agency because it:','["ends oversight", "hides problems", "avoids questions", "builds community trust and understanding"]'::jsonb,3,'Communication builds trust.','original'),
('127.747.d.11.A',3,'Direct supervision, indirect supervision and intermittent supervision describe the three main:','["models of detention facilities", "school schedules", "court levels", "police ranks"]'::jsonb,0,'Detention facilities use these supervision models.','original'),
('127.747.d.11.A',4,'In a direct supervision facility, officers:','["never interact", "stay inside the housing unit with the inmates", "watch only by camera", "stay outside the building"]'::jsonb,1,'Direct supervision places staff among inmates.','original'),
('127.747.d.11.B',3,'A detention officer''s core duties include maintaining security, supervising inmates and:','["setting court dates", "writing laws", "keeping accurate records of activity", "choosing judges"]'::jsonb,2,'Officers document events.','original'),
('127.747.d.11.B',4,'Which duty is central to a detention officer''s role?','["Setting bail amounts", "Prosecuting cases", "Passing laws", "Ensuring the safety and security of the facility"]'::jsonb,3,'Safety and security come first.','original'),
('127.747.d.11.C',3,'An inmate claims they were denied needed medical care. This raises an issue of:','["prisoners'' constitutional rights", "clothing colors", "menu preferences", "TV channels"]'::jsonb,0,'Medical care is a constitutional issue.','original'),
('127.747.d.11.C',4,'Which issue involves prisoners'' constitutional rights?','["picking visiting day", "protection from cruel and unusual punishment", "selecting a meal brand", "choosing a cell color"]'::jsonb,1,'The Eighth Amendment applies.','original'),
('127.747.d.12.A',3,'An officer is offered a favor by an inmate for looking away from a rule. Rejecting it shows the importance of:','["personal gain", "carelessness", "ethical judgment and behavior in criminal justice", "dishonesty"]'::jsonb,2,'Ethics guide professional behavior.','original'),
('127.747.d.12.A',4,'Ethical behavior in criminal justice work means:','["favoring friends", "hiding errors", "bending rules", "acting honestly and fairly even when no one is watching"]'::jsonb,3,'Integrity is consistent.','original'),
('127.747.d.12.B',3,'Officers must keep professional boundaries and avoid personal relationships with inmates. This is a human-relations issue between:','["staff and prisoners", "court and press", "teachers and parents", "fire and EMS"]'::jsonb,0,'Boundaries protect safety and fairness.','original'),
('127.747.d.12.B',4,'Which is a human-relations issue between staff and prisoners?','["building signs", "maintaining fairness and professional boundaries", "choosing uniforms", "buying lunch"]'::jsonb,1,'Fair treatment avoids favoritism.','original'),
('127.747.d.12.C',3,'Both inmates and officers face stress, but officers may deal with long shifts and danger while inmates deal with confinement. This is:','["ignoring stress", "only a hobby", "comparing stress and stress-related issues for correctional staff and inmates", "only a vacation"]'::jsonb,2,'Stress affects both groups differently.','original'),
('127.747.d.12.C',4,'A healthy way for correctional personnel to cope with stress is to:','["skip sleep", "avoid help", "ignore symptoms", "use exercise, rest and support programs"]'::jsonb,3,'Healthy coping lowers stress.','original'),
('127.747.d.12.D',3,'A county jail holds training so staff understand the customs and needs of the diverse people they supervise. This is:','["promoting cultural awareness in corrections", "creating conflict", "avoiding training", "ignoring differences"]'::jsonb,0,'Awareness improves respect and safety.','original'),
('127.747.d.12.D',4,'Cultural awareness training helps officers:','["ignore needs", "communicate respectfully and avoid misunderstandings", "show bias", "avoid all training"]'::jsonb,1,'Understanding reduces conflict.','original'),
('127.747.d.12.E',3,'Laws that protect employees and inmates from discrimination and harassment are:','["traffic laws only", "school rules only", "state and federal civil rights laws", "tax laws only"]'::jsonb,2,'Civil rights laws cover harassment and discrimination.','original'),
('127.747.d.12.E',4,'Sexual harassment of a coworker or inmate by staff is:','["permitted", "a privilege", "a joke", "prohibited by law and agency policy"]'::jsonb,3,'It violates civil rights law.','original'),
('127.747.d.13.A',3,'During intake, a nurse asks questions to see whether a new inmate is at risk of self-harm. This is a method of:','["screening for suicide risk", "sentencing", "booking photos", "parole review"]'::jsonb,0,'Screening identifies risk early.','original'),
('127.747.d.13.A',4,'Screening for suicide risk at intake typically includes:','["ignoring answers", "asking about past attempts, current thoughts and recent stressors", "only taking photos", "only asking height"]'::jsonb,1,'Intake questions reveal risk.','original'),
('127.747.d.13.B',3,'A facility places an at-risk inmate on observation and alerts mental health staff. This is a procedure for:','["punishing", "isolating forever", "preventing suicide among prisoners", "ignoring signs"]'::jsonb,2,'Observation and referral save lives.','original'),
('127.747.d.13.B',4,'If an officer finds an inmate attempting to self-harm, the officer should:','["ignore", "leave", "wait", "call for help and begin emergency aid"]'::jsonb,3,'Immediate response is required.','original'),
('127.747.d.13.C',3,'A newly booked person arrives shaking and confused after heavy drinking. Staff must classify and deal with:','["intoxicated persons safely and promptly", "only clothing", "only paperwork", "only meals"]'::jsonb,0,'Intoxication can be a medical emergency.','original'),
('127.747.d.13.C',4,'Why must officers monitor intoxicated detainees closely?','["It speeds booking", "Intoxication or withdrawal can cause medical emergencies", "It''s fun", "It is unneeded"]'::jsonb,1,'Withdrawal can be dangerous.','original'),
('127.747.d.14.A',3,'At booking, an officer records personal data, takes fingerprints and inventories belongings. These are:','["parole procedures", "court procedures", "general booking procedures", "hiring procedures"]'::jsonb,2,'Booking creates the record.','original'),
('127.747.d.14.A',4,'Which step is part of booking?','["granting parole", "approving a loan", "issuing a diploma", "fingerprinting and photographing the person"]'::jsonb,3,'Fingerprints and photos are standard.','original'),
('127.747.d.14.B',3,'After booking, medical screening and classification occur before assignment to a cell. This is part of the:','["prisoner admission process", "appeal", "release process", "trial"]'::jsonb,0,'Admission includes screening and classification.','original'),
('127.747.d.14.B',4,'The admission process for a new prisoner typically includes:','["a trial", "medical screening, property inventory and classification", "a vote", "graduation"]'::jsonb,1,'Admission steps prepare placement.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_94_v1'
from (values
('127.747.d.14.C',3,'An officer verifies identity, returns property and records the time when someone leaves custody. This is the:','["booking process", "trial process", "process for releasing prisoners", "parole denial"]'::jsonb,2,'Release has set steps.','original'),
('127.747.d.14.C',4,'Before releasing a prisoner, staff must confirm:','["their favorite color", "their shoe size", "their lunch choice", "the person''s identity and the legal authority for release"]'::jsonb,3,'Identity and authority prevent errors.','original'),
('127.747.d.15.A',3,'An officer notices an inmate muttering and refusing to eat for days and reports it. This is identifying:','["symptoms of a mental impairment", "a hobby", "normal behavior always", "nothing"]'::jsonb,0,'Behavior changes can signal illness.','original'),
('127.747.d.15.A',4,'Which observed change might signal a mental health issue in an inmate?','["reading", "sudden withdrawal, confusion or extreme mood swings", "routine exercise", "a regular meal"]'::jsonb,1,'Sudden changes warrant referral.','original'),
('127.747.d.15.B',3,'At intake, staff ask an inmate whether they have ever been treated for mental illness or taken psychiatric medication. These are:','["menu choices", "clothing sizes", "screening questions for mental illness", "visiting rules"]'::jsonb,2,'Screening questions identify needs.','original'),
('127.747.d.15.B',4,'A screening question for mental illness at booking would be:','["What is your car color?", "What is your favorite food?", "What sport do you play?", "Have you ever received mental health treatment or medication?"]'::jsonb,3,'History informs care.','original'),
('127.747.d.15.C',3,'Staff keep an inmate''s medical file secure and share it only with authorized people. This is:','["maintaining health records with attention to privacy", "deleting files", "ignoring privacy", "sharing publicly"]'::jsonb,0,'Health records are confidential.','original'),
('127.747.d.15.C',4,'Why are inmate health records kept confidential?','["Anyone may read them", "Privacy laws and policy protect sensitive medical information", "Records are worthless", "They are entertainment"]'::jsonb,1,'Confidentiality is required.','original'),
('127.747.d.15.D',3,'A court rules that jails must provide necessary medical care. This is a:','["staff dress code", "visiting-hours rule", "legal aspect of health care in a detention facility", "menu rule"]'::jsonb,2,'Law requires adequate care.','original'),
('127.747.d.15.D',4,'Which statement is true about health care in a detention facility?','["No care is ever allowed", "Only staff get care", "Care is optional", "Facilities have a legal duty to provide necessary medical care"]'::jsonb,3,'Deliberate indifference violates rights.','original'),
('127.747.d.16',3,'A jail provides visitation, mail, library access, religious services and phone calls. These are:','["various prisoner services", "staff benefits", "court services", "school services"]'::jsonb,0,'Prisoners receive regulated services.','original'),
('127.747.d.16',4,'Providing prisoner services such as mail and visitation requires facilities to:','["eliminate all services", "follow rules that balance access and security", "ignore security", "allow unlimited contraband"]'::jsonb,1,'Services are provided within security limits.','original'),
('127.747.d.17.A',3,'Officers count every inmate at set times to be sure no one is missing. This identifies the importance of:','["staff parties", "court dates", "inmate counts", "menu planning"]'::jsonb,2,'Counts verify everyone is accounted for.','original'),
('127.747.d.17.A',4,'If an inmate count does not match the expected total, officers should:','["guess", "skip the count", "ignore it", "recount and notify a supervisor"]'::jsonb,3,'Discrepancies must be resolved.','original'),
('127.747.d.17.B',3,'An officer lists each item a new inmate brings in, seals it in a bag and has the inmate sign. This is:','["inventorying a prisoner''s property", "searching a cell", "releasing the person", "writing a report"]'::jsonb,0,'Property must be documented.','original'),
('127.747.d.17.B',4,'Why is an inventory of prisoner property signed by the inmate?','["It''s fun", "It documents what was received and prevents disputes", "It''s not needed", "It hides items"]'::jsonb,1,'Signatures create a record.','original'),
('127.747.d.17.C',3,'Searching a prisoner requires officers to follow rules about the person''s gender and privacy. This is the process of:','["skipping the search", "ignoring privacy", "searching male and female prisoners properly", "searching at random"]'::jsonb,2,'Search rules protect dignity and safety.','original'),
('127.747.d.17.C',4,'A pat-down search of a prisoner should be performed by an officer who:','["is untrained", "picks anyone", "avoids policy", "follows policy and, when required, is of the same gender"]'::jsonb,3,'Policy dictates who searches.','original'),
('127.747.d.17.D',3,'Officers check beds, vents and shared tables for hidden weapons or drugs. This is the process for:','["searching cells and common areas", "parole", "trial", "booking"]'::jsonb,0,'Cell searches detect contraband.','original'),
('127.747.d.17.D',4,'The main purpose of searching cells and common areas is to find:','["art projects", "contraband and security threats", "furniture brands", "menu items"]'::jsonb,1,'Searches protect safety.','original'),
('127.747.d.17.E',3,'Broken locks, propped doors and unsecured keys are examples of:','["kitchen duties", "fashion choices", "issues involving facility security", "housekeeping goals"]'::jsonb,2,'They create security risks.','original'),
('127.747.d.17.E',4,'Which practice helps maintain facility security?','["Ignoring broken locks", "Leaving doors propped", "Sharing keys freely", "Controlling keys and checking locks regularly"]'::jsonb,3,'Key control is basic.','original'),
('127.747.d.18.A',3,'Staff follow a plan to regain control when many inmates refuse orders at once. This is a procedure for:','["responding to a riot or disturbance", "a food delivery", "a parole hearing", "a booking"]'::jsonb,0,'Riots require coordinated response.','original'),
('127.747.d.18.A',4,'The first priority for staff responding to a disturbance is to:','["join in", "protect life and secure the area", "ignore it", "leave the post"]'::jsonb,1,'Safety and control first.','original'),
('127.747.d.18.B',3,'Officers practice what to do for an assault, a fire or a medical emergency inside a housing unit. These are:','["school plans", "parking plans", "procedures for responding to emergency events", "recipes"]'::jsonb,2,'Training prepares for varied emergencies.','original'),
('127.747.d.18.B',4,'When a fire alarm sounds in a unit, staff should:','["wait", "hide", "ignore it", "follow the evacuation plan and account for inmates"]'::jsonb,3,'Plans protect people.','original'),
('127.747.d.18.C',3,'An officer deals with an inmate who repeatedly shouts and disrupts a group. This is a problem with:','["disruptive inmates and groups", "parole", "booking", "court procedure"]'::jsonb,0,'Disruptive behavior must be managed.','original'),
('127.747.d.18.C',4,'A good first response to a disruptive inmate is to:','["ignore", "give a clear verbal direction and use de-escalation", "use force immediately", "argue"]'::jsonb,1,'Start with the least force.','original'),
('127.747.d.18.D',3,'After a missing inmate is discovered, staff lock down the facility, notify law enforcement and search. This is the procedure for:','["release", "intake", "escape attempts and escapes", "parole"]'::jsonb,2,'Escapes trigger specific steps.','original'),
('127.747.d.18.D',4,'When an escape is suspected, staff should immediately:','["tell the media first", "ignore it", "wait a day", "secure the facility and notify supervisors and law enforcement"]'::jsonb,3,'Rapid notification is key.','original'),
('127.747.d.19.A',3,'After an incident, an officer writes facts, times and actions in order and checks for accuracy. This shows the process of:','["writing reports", "deleting evidence", "guessing", "ignoring events"]'::jsonb,0,'Accurate reports matter.','original'),
('127.747.d.19.A',4,'A good incident report is:','["emotional", "factual, objective and complete", "biased", "vague"]'::jsonb,1,'Reports must be reliable.','original'),
('127.747.d.19.B',3,'An officer who must testify in court wears a clean uniform, speaks respectfully and stays calm. This is:','["casual dress", "ignoring the judge", "appropriate courtroom attire and demeanor", "arguing"]'::jsonb,2,'Professional appearance matters.','original'),
('127.747.d.19.B',4,'Which demeanor is appropriate for a witness in court?','["angry", "evasive", "joking", "calm, respectful and truthful"]'::jsonb,3,'Credibility depends on demeanor.','original'),
('127.747.d.19.C',3,'Before testifying, an officer reviews notes and reports and meets with the prosecutor. This is:','["preparing for courtroom testimony", "skipping prep", "guessing", "avoiding court"]'::jsonb,0,'Preparation ensures accurate testimony.','original'),
('127.747.d.19.C',4,'To prepare for testimony, an officer should:','["memorize a script of lies", "review reports and be ready to answer truthfully", "skip review", "avoid the prosecutor"]'::jsonb,1,'Truth and preparation matter.','original'),
('127.747.d.20.A',3,'In a training simulation, an officer moves from verbal commands to physical control only as the threat increases. This demonstrates the:','["use of no force", "use of random force", "use of the force continuum", "use of ranks"]'::jsonb,2,'The continuum escalates with the threat.','original'),
('127.747.d.20.A',4,'On the force continuum, the lowest level of response is usually:','["deadly force", "restraints only", "chemical agents", "officer presence and verbal commands"]'::jsonb,3,'Start with the least force.','original'),
('127.747.d.20.B',3,'State and federal laws limit how much force officers may use. These are:','["guidelines and restrictions on use of force", "optional", "suggestions only", "rumors"]'::jsonb,0,'Law restricts force.','original'),
('127.747.d.20.B',4,'Which statement describes legal limits on force by corrections officers?','["Force is optional", "Force must be reasonable and no more than necessary", "Force is for punishment", "Force is unlimited"]'::jsonb,1,'Reasonable force only.','original'),
('127.747.d.21',3,'A homeland security trainee practices breaking free from a hold and calling for help. This is analyzing:','["ignoring risk", "hiding", "procedures and protocols for self-defense", "avoiding training"]'::jsonb,2,'Self-defense procedures protect officers.','original'),
('127.747.d.21',4,'Self-defense protocols in homeland security emphasize:','["attacking first", "avoiding rules", "unlimited force", "protecting oneself and others using only necessary and lawful force"]'::jsonb,3,'Self-defense must be lawful.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
